type Sym[R any] interface {
    Lit(i int) R
    Add(a, b R) R
}

func Exp[R any](s Sym[R]) R { return s.Add(s.Lit(1), s.Add(s.Lit(2), s.Lit(4))) }

type Eval struct{}
func (Eval) Lit(i int) int    { return i }
func (Eval) Add(a, b int) int { return a + b }

